import {
  Scene,
  Mesh,
  MeshPhysicalMaterial,
  DoubleSide,
} from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';

/**
 * Transmissive glass slab — positioned behind the DOM form.
 *
 * The DOM form is a translucent card on top of the canvas; this 3D glass slab
 * sits in scene-space at roughly the same screen region, refracting whatever's
 * behind it (the pillar). Together they read as "the form is glass."
 *
 * Slice 3 — first appearance. Position is hard-coded for an approximate match
 * against the new layout; Slice 5 will project the DOM form's bounding rect
 * to world coords each frame for pixel-accurate alignment.
 *
 * Requirements for transmission to render:
 *   - scene.environment must be set (Slice 2: setupEnvironment provides this)
 *   - renderer.toneMapping should be set (Slice 1: ACES filmic)
 *   - The slab needs depth — even a 0.06 thickness produces meaningful refraction
 */

export interface GlassHandle {
  mesh: Mesh;
  dispose(): void;
}

/**
 * Build the glass slab and add it to the scene.
 *
 * Default world placement matches the new composition (form on the screen-right,
 * pillar on the screen-left). Callers may reposition `handle.mesh` afterward.
 *
 * `transmissionStrength` is tier-gated: 1.0 on desktop, lower on mobile where
 * the transmission render target is expensive. Below ~0.4 the refraction is
 * subtle enough that the glass reads more like a backdrop-filter blur.
 */
export function createGlassCard(
  scene: Scene,
  transmissionStrength: number = 1.0,
): GlassHandle {
  const geometry = new RoundedBoxGeometry(1.85, 2.55, 0.08, 6, 0.16);

  const material = new MeshPhysicalMaterial({
    color: 0xffffff,
    transmission: transmissionStrength,
    thickness: 0.5,
    roughness: 0.18,
    ior: 1.45,
    metalness: 0.0,
    clearcoat: 1.0,
    clearcoatRoughness: 0.05,
    attenuationColor: 0xC9F2E0,
    attenuationDistance: 1.8,
    envMapIntensity: 1.0,
    side: DoubleSide,
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(1.55, 1.55, 0.6);
  mesh.rotation.y = -0.18;
  // Glass doesn't cast useful shadows under transmission, and the shadow map
  // would fight the refraction visually.
  mesh.castShadow = false;
  mesh.receiveShadow = false;

  scene.add(mesh);

  return {
    mesh,
    dispose(): void {
      scene.remove(mesh);
      geometry.dispose();
      material.dispose();
    },
  };
}
