/**
 * Responsive scene tiers.
 *
 * Three tiers, picked from viewport width at mount time. Each downgrades
 * GPU cost progressively. Tier is fixed for the lifetime of a scene — we
 * don't re-tier on resize because rebuilding shadow maps + post-FX
 * resources mid-session would stutter visibly.
 *
 * Roughly aligned with the blueprint's §8 perf budget targets.
 */

export type Tier = 'cinematic' | 'compact' | 'mobile';

export interface TierConfig {
  /** Cap on devicePixelRatio for the renderer. */
  pixelRatio: number;
  /** Square dimension for directional shadow maps. */
  shadowMap: number;
  /** InstancedMesh particle count for the atmospheric drift. */
  particles: number;
  /** Whether to mount the EffectComposer + bloom + tone-map pass. */
  postFX: boolean;
  /** Bloom strength when postFX is enabled. */
  bloomStrength: number;
  /** Whether to track pointer for parallax (camera + rim sweep). */
  parallax: boolean;
  /** Glass slab transmission strength — full PBR refraction at 1.0, cheaper at 0.5. */
  glassTransmission: number;
  /** Frame-skip ratio when the scene is "idle" (no pointer movement, no active tween). */
  idleFrameSkip: number;
}

const CINEMATIC: TierConfig = {
  pixelRatio: 1.75,
  shadowMap: 2048,
  particles: 256,
  postFX: true,
  bloomStrength: 0.55,
  parallax: true,
  glassTransmission: 1.0,
  idleFrameSkip: 2,
};

const COMPACT: TierConfig = {
  pixelRatio: 1.5,
  shadowMap: 1024,
  particles: 128,
  postFX: true,
  bloomStrength: 0.45,
  parallax: true,
  glassTransmission: 0.85,
  idleFrameSkip: 2,
};

const MOBILE: TierConfig = {
  pixelRatio: 1.25,
  shadowMap: 512,
  particles: 64,
  postFX: false,
  bloomStrength: 0,
  parallax: false,
  glassTransmission: 0.5,
  idleFrameSkip: 3,
};

const CONFIGS: Record<Tier, TierConfig> = {
  cinematic: CINEMATIC,
  compact: COMPACT,
  mobile: MOBILE,
};

export function pickTier(): Tier {
  if (typeof window === 'undefined') return 'cinematic';
  if (window.matchMedia('(min-width: 1280px)').matches) return 'cinematic';
  if (window.matchMedia('(min-width: 768px)').matches) return 'compact';
  return 'mobile';
}

export function tierConfig(tier: Tier): TierConfig {
  return CONFIGS[tier];
}
