import { Vector2 } from 'three';
import type { PerspectiveCamera, WebGLRenderer, SpotLight, Vector3 } from 'three';

/**
 * Pointer + resize plumbing.
 *
 * Slice 1: resize only.
 * Slice 4: pointer parallax + rim-light follow. The pointer state is shared
 *          between the watcher (input) and the tick driver (output), and the
 *          smoothed values are exposed so other systems (e.g. glass z-push on
 *          focus) can compose against them.
 */

export interface PointerState {
  /** Raw NDC pointer (-1..1, top-left origin → bottom-right). */
  target: Vector2;
  /** Critically-damped pointer for smooth motion. */
  smoothed: Vector2;
  /** Last time the pointer moved, in performance.now() ms. */
  lastMoveAt: number;
}

export function createPointerState(): PointerState {
  return {
    target: new Vector2(0, 0),
    smoothed: new Vector2(0, 0),
    lastMoveAt: 0,
  };
}

export interface PointerWatcher {
  dispose(): void;
}

/** Listens for pointer movement on the window and updates the shared state. */
export function watchPointer(pointer: PointerState): PointerWatcher {
  const onMove = (e: PointerEvent): void => {
    pointer.target.x = (e.clientX / window.innerWidth) * 2 - 1;
    pointer.target.y = (e.clientY / window.innerHeight) * 2 - 1;
    pointer.lastMoveAt = performance.now();
  };
  window.addEventListener('pointermove', onMove, { passive: true });
  return {
    dispose: () => window.removeEventListener('pointermove', onMove),
  };
}

export interface ParallaxConfig {
  /** Camera origin before any parallax offset. */
  cameraBase: Vector3;
  /** Where the camera should be looking when pointer is at (0, 0). */
  cameraLookAt: Vector3;
  /** How far the camera drifts on each axis (world units per NDC unit). */
  cameraAmplitude: { x: number; y: number };
  /** Rim spotlight origin before any parallax offset. */
  rimBase: { x: number; y: number; z: number };
  /** How far the rim sweeps with cursor x; z grows with |cursor x|. */
  rimAmplitude: { x: number; z: number };
  /** Lerp factor per frame; 0.08 = critically damped at 60 Hz. */
  damping: number;
}

/**
 * Per-frame parallax tick. Mutates camera and rim positions in place.
 *
 * Call this every frame from the main RAF loop, after updating pointer.target
 * (which the watcher does automatically). The smoothed pointer is updated as
 * a side-effect so other consumers can read it.
 */
export function tickParallax(
  pointer: PointerState,
  camera: PerspectiveCamera,
  rim: SpotLight,
  cfg: ParallaxConfig,
): void {
  pointer.smoothed.x += (pointer.target.x - pointer.smoothed.x) * cfg.damping;
  pointer.smoothed.y += (pointer.target.y - pointer.smoothed.y) * cfg.damping;

  camera.position.x = cfg.cameraBase.x + pointer.smoothed.x * cfg.cameraAmplitude.x;
  camera.position.y = cfg.cameraBase.y + -pointer.smoothed.y * cfg.cameraAmplitude.y;
  camera.position.z = cfg.cameraBase.z;
  camera.lookAt(cfg.cameraLookAt);

  rim.position.x = cfg.rimBase.x + pointer.smoothed.x * cfg.rimAmplitude.x;
  rim.position.z = cfg.rimBase.z + Math.abs(pointer.smoothed.x) * cfg.rimAmplitude.z;
  rim.target.updateMatrixWorld();
}

/* ───────────────────────── Resize ───────────────────────── */

export interface ResizeWatcher {
  dispose(): void;
}

export function watchResize(
  canvas: HTMLCanvasElement,
  camera: PerspectiveCamera,
  renderer: WebGLRenderer,
): ResizeWatcher {
  const apply = (): void => {
    const w = canvas.clientWidth;
    const h = canvas.clientHeight;
    if (w === 0 || h === 0) return;
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h, false);
  };

  const ro = new ResizeObserver(apply);
  ro.observe(canvas);
  const onWindowResize = (): void => apply();
  window.addEventListener('resize', onWindowResize);

  return {
    dispose: () => {
      ro.disconnect();
      window.removeEventListener('resize', onWindowResize);
    },
  };
}
