import {
  Scene,
  Group,
  Mesh,
  Box3,
  Vector3,
  CylinderGeometry,
  BoxGeometry,
  SphereGeometry,
  InstancedMesh,
  InstancedBufferAttribute,
  SRGBColorSpace,
  Object3D,
  Material,
  MeshStandardMaterial,
  Texture,
} from 'three';
import { GLTFLoader, type GLTF } from 'three/examples/jsm/loaders/GLTFLoader.js';
import {
  basePlatformMaterial,
  brandColumnMaterial,
  headMaterial,
  cableMaterial,
  connectorMaterial,
  ledMaterial,
  particleMaterial,
} from './Materials.js';

/**
 * Charging-station model loading & fallback geometry.
 *
 * Slice 3 refactor — the fallback parts + atmospheric particles are now wrapped
 * in a single Group exposed via `handle.root`, so the caller can position the
 * whole assembly off-center for the glass-overlap composition.
 *
 * Behavioural notes preserved from Slice 1-2:
 *   - LED pulse driven by the scene clock (frame-locked, not setTimeout)
 *   - Particle motion ticked from the main RAF, no second rAF
 *   - PBR materials (Slice 2) pick up scene.environment for IBL
 */

export interface ChargingStationHandle {
  /** Root Object3D — translate/rotate this to move the whole assembly as a unit. */
  root: Object3D;
  /**
   * Primary emissive material — for the fallback this is the LED; for GLB
   * we return null (GLB-author intent is preserved). Slice 4 tweens this for
   * focus emphasis and the error flash.
   */
  emissive: MeshStandardMaterial | null;
  /** Called every frame from the main RAF loop. */
  tick(elapsedSeconds: number): void;
  /** Releases all GPU resources owned by this model. */
  dispose(): void;
}

export async function loadChargingStation(
  scene: Scene,
  modelUrl: string | null | undefined,
  particleCount: number = 256,
): Promise<ChargingStationHandle> {
  if (modelUrl) {
    try {
      return await loadGltf(scene, modelUrl);
    } catch (err) {
      console.error('[login3d] GLB load failed, using fallback:', err);
    }
  }
  return createFallbackChargingStation(scene, particleCount);
}

function loadGltf(scene: Scene, url: string): Promise<ChargingStationHandle> {
  return new Promise((resolve, reject) => {
    const loader = new GLTFLoader();
    loader.load(
      url,
      (gltf: GLTF) => {
        const model = gltf.scene;

        model.traverse((child: Object3D) => {
          if ((child as Mesh).isMesh) {
            const mesh = child as Mesh;
            mesh.castShadow = true;
            mesh.receiveShadow = true;

            const mats: Material[] = Array.isArray(mesh.material)
              ? mesh.material
              : [mesh.material];
            for (const mat of mats) {
              applyTextureColorSpace(mat as MeshStandardMaterial);
              mat.needsUpdate = true;
            }
          }
        });

        // Center + uniform scale to ~3 units max dim.
        const box = new Box3().setFromObject(model);
        const center = box.getCenter(new Vector3());
        const size = box.getSize(new Vector3());

        model.position.sub(center);
        const maxDim = Math.max(size.x, size.y, size.z);
        const scale = 3 / maxDim;
        model.scale.setScalar(scale);
        model.position.y = -box.min.y * scale;

        scene.add(model);

        resolve({
          root: model,
          emissive: null,
          tick: () => {
            /* GLB path: no per-mesh ticking */
          },
          dispose: () => {
            scene.remove(model);
            disposeObject(model);
          },
        });
      },
      undefined,
      (err) => reject(err),
    );
  });
}

function applyTextureColorSpace(mat: MeshStandardMaterial): void {
  const colorTextures: (keyof MeshStandardMaterial)[] = [
    'map',
    'emissiveMap',
  ];
  for (const key of colorTextures) {
    const tex = mat[key] as Texture | null | undefined;
    if (tex) tex.colorSpace = SRGBColorSpace;
  }
  // normalMap stays linear (correct PBR behavior — the original inline code
  // was setting it to sRGB which is a bug we don't replicate).
}

export function createFallbackChargingStation(
  scene: Scene,
  particleCount: number = 256,
): ChargingStationHandle {
  const root = new Group();
  root.name = 'login-fallback-pillar';

  // Base platform
  const base = new Mesh(new CylinderGeometry(2, 2, 0.2, 32), basePlatformMaterial());
  base.position.y = -0.1;
  base.receiveShadow = true;
  root.add(base);

  // Main column — EVON-green lacquered.
  const column = new Mesh(new CylinderGeometry(0.3, 0.4, 3, 16), brandColumnMaterial());
  column.position.y = 1.4;
  column.castShadow = true;
  root.add(column);

  // Charging head — black painted metal.
  const head = new Mesh(new BoxGeometry(0.8, 0.6, 0.4), headMaterial());
  head.position.set(0.6, 2.8, 0);
  head.castShadow = true;
  root.add(head);

  // Cable — matte rubber.
  const cable = new Mesh(new CylinderGeometry(0.02, 0.02, 2, 8), cableMaterial());
  cable.position.set(0.6, 1.5, 0);
  cable.rotation.z = Math.PI / 4;
  cable.castShadow = true;
  root.add(cable);

  // Connector — glossy red.
  const connector = new Mesh(new SphereGeometry(0.1, 16, 16), connectorMaterial());
  connector.position.set(1.2, 2.2, 0);
  connector.castShadow = true;
  root.add(connector);

  // Status LED — emissive green, toggles every 1.0s.
  const ledMat = ledMaterial(0x22c55e);
  const led = new Mesh(new SphereGeometry(0.05, 16, 16), ledMat);
  led.position.set(0.6, 3.1, 0.2);
  root.add(led);

  // Floating particles — InstancedMesh, one draw call for the whole field.
  // Motion is shader-driven (per-instance aSeed × uTime) so the CPU touches
  // nothing once the instance matrices are uploaded. Count is tier-gated.
  const PARTICLE_COUNT = particleCount;
  const particleGeo = new SphereGeometry(0.018, 6, 6);
  const particleMat = particleMaterial();

  const particleShaderRef: { shader: { uniforms: { uTime: { value: number } } } | null } = { shader: null };
  particleMat.onBeforeCompile = (shader) => {
    shader.uniforms['uTime'] = { value: 0 };
    particleShaderRef.shader = shader as unknown as typeof particleShaderRef.shader;
    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <common>',
        `#include <common>
         attribute float aSeed;
         uniform float uTime;`,
      )
      .replace(
        '#include <begin_vertex>',
        `vec3 transformed = vec3( position );
         float s = aSeed;
         float t = uTime * 0.4;
         transformed.x += sin(t + s * 6.28) * 0.35;
         transformed.y += cos(t * 0.6 + s * 12.56) * 0.45;
         transformed.z += sin(t * 0.8 + s * 18.84) * 0.30;`,
      );
  };

  const particles = new InstancedMesh(particleGeo, particleMat, PARTICLE_COUNT);
  particles.castShadow = false;
  particles.receiveShadow = false;

  const dummy = new Object3D();
  const seeds = new Float32Array(PARTICLE_COUNT);
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    const r = 2.2 + Math.random() * 2.4;
    const a = Math.random() * Math.PI * 2;
    dummy.position.set(
      Math.cos(a) * r,
      Math.random() * 3.6 + 0.2,
      Math.sin(a) * r - 0.5,
    );
    dummy.updateMatrix();
    particles.setMatrixAt(i, dummy.matrix);
    seeds[i] = Math.random();
  }
  particles.instanceMatrix.needsUpdate = true;
  particleGeo.setAttribute('aSeed', new InstancedBufferAttribute(seeds, 1));

  root.add(particles);
  scene.add(root);

  let lastLedToggle = 0;

  const tick = (elapsedSeconds: number): void => {
    // LED 1-second pulse: toggle color + emissive between two greens.
    if (elapsedSeconds - lastLedToggle >= 1) {
      lastLedToggle = elapsedSeconds;
      const next = ledMat.color.getHex() === 0x22c55e ? 0x16a34a : 0x22c55e;
      ledMat.color.setHex(next);
      ledMat.emissive.setHex(next);
    }

    // Particle drift is shader-driven — we only push the time uniform.
    if (particleShaderRef.shader) {
      particleShaderRef.shader.uniforms.uTime.value = elapsedSeconds;
    }
  };

  const dispose = (): void => {
    scene.remove(root);
    disposeObject(root);
  };

  return { root, emissive: ledMat, tick, dispose };
}

function disposeMesh(mesh: Mesh): void {
  mesh.geometry?.dispose();
  if (Array.isArray(mesh.material)) {
    for (const m of mesh.material) m.dispose();
  } else {
    mesh.material?.dispose();
  }
}

function disposeObject(root: Object3D): void {
  root.traverse((child) => {
    if ((child as Mesh).isMesh) disposeMesh(child as Mesh);
  });
}
