import { Clock, Vector3, type Texture, type MeshStandardMaterial } from 'three';
import { gsap } from 'gsap';

import { createRenderer, createScene, createCamera } from './Scene.js';
import { setupLights, setupEnvironment, setupRimLight, type RimLight } from './Lighting.js';
import { loadChargingStation, type ChargingStationHandle } from './Models.js';
import { createGlassCard, type GlassHandle } from './Glass.js';
import { createPostFX, type PostFXHandle } from './PostFX.js';
import {
  watchResize,
  watchPointer,
  createPointerState,
  tickParallax,
  type ParallaxConfig,
} from './Interactions.js';
import { pickTier, tierConfig, type Tier } from './tiers.js';

import type { LoginSceneHandle, LoginSceneOptions } from './types.js';
export type { LoginSceneHandle, LoginSceneOptions };

/**
 * Mount the EVON login 3D scene onto a canvas element.
 *
 * Slice 5 — production polish:
 *   - Responsive perf tiers (cinematic ≥ 1280, compact ≥ 768, else mobile)
 *   - Post-processing on desktop tiers (UnrealBloomPass + OutputPass)
 *   - DOM-anchored glass slab (the 3D glass tracks the .login-card rect)
 *   - Render-on-demand when idle (drops to ~30 fps if pointer is still)
 *   - prefers-reduced-motion still wins over everything (one still frame)
 */
export function mountLoginScene(
  canvas: HTMLCanvasElement,
  opts: LoginSceneOptions = {},
): LoginSceneHandle {
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const tier: Tier = opts.tier ?? pickTier();
  const cfg = tierConfig(tier);

  const scene = createScene();
  const camera = createCamera(canvas);
  const renderer = createRenderer(canvas, cfg.pixelRatio);

  setupLights(scene, cfg.shadowMap);
  const envTexture: Texture = setupEnvironment(scene, renderer);
  const rim: RimLight = setupRimLight(scene);

  // Glass card mounted before the model so the pillar (when it resolves)
  // renders into the transmission render target behind the glass.
  const glass: GlassHandle = createGlassCard(scene, cfg.glassTransmission);
  const glassBaseZ = glass.mesh.position.z;
  const glassFocusedZ = glassBaseZ - 0.2;

  // Glass tracks the DOM anchor (the .login-card) each frame — see alignGlass()
  // below. Without an anchor, the glass keeps its hard-coded default position.
  const glassAnchor: HTMLElement | null = opts.glassAnchor ?? null;

  // Async model load — pillar shifts left so it doesn't sit directly behind
  // the glass. Particle count gated by tier.
  let modelHandle: ChargingStationHandle | null = null;
  let modelEmissive: MeshStandardMaterial | null = null;
  let emissiveBaseIntensity = 0;

  void loadChargingStation(scene, opts.modelUrl ?? null, cfg.particles).then((h) => {
    modelHandle = h;
    modelHandle.root.position.x = -0.8;
    modelEmissive = h.emissive;
    if (modelEmissive) {
      emissiveBaseIntensity = modelEmissive.emissiveIntensity;
    }
  });

  const parallaxCfg: ParallaxConfig = {
    cameraBase: new Vector3(0, 1.6, 5.5),
    cameraLookAt: new Vector3(0.2, 1.1, 0),
    cameraAmplitude: { x: 0.35, y: 0.15 },
    rimBase: { ...rim.basePosition },
    rimAmplitude: { x: 1.5, z: 0.5 },
    damping: 0.08,
  };

  const pointer = createPointerState();
  // Mark "just moved" at mount so the first IDLE_MS window renders at full rate,
  // even on touch devices where pointer never actually moves. Without this,
  // mobile users would see the scene at idle-throttled rate from frame one.
  pointer.lastMoveAt = performance.now();
  const pointerWatcher = (cfg.parallax && !reducedMotion) ? watchPointer(pointer) : null;

  /* ──────────────── Post-processing ──────────────── */
  let postFX: PostFXHandle | null = null;
  if (cfg.postFX && !reducedMotion) {
    postFX = createPostFX(scene, camera, renderer, {
      bloomStrength: cfg.bloomStrength,
      bloomRadius: 0.6,
      bloomThreshold: 0.78,
    });
  }

  /* ──────────────── Resize (extended to drive composer too) ──────────────── */
  const resizeWatcher = watchResize(canvas, camera, renderer);
  // Tag a hook on resize to also resize the composer. The watchResize helper
  // doesn't expose a callback API, so we observe the canvas independently.
  const composerResizeRO = new ResizeObserver(() => {
    if (!postFX) return;
    postFX.resize(canvas.clientWidth, canvas.clientHeight, renderer.getPixelRatio());
  });
  composerResizeRO.observe(canvas);

  /* ──────────────── Glass-to-DOM anchor alignment ──────────────── */
  // Reusable scratch Vector3 so we don't churn allocations per frame.
  const ndcScratch = new Vector3();
  const worldScratch = new Vector3();

  function alignGlass(): void {
    if (!glassAnchor) return;
    const rect = glassAnchor.getBoundingClientRect();
    if (rect.width === 0 || rect.height === 0) return;

    // 1) Find the world point at the glass plane's z that projects to the
    //    DOM rect's center, via a camera ray.
    const cx = (rect.left + rect.width / 2) / window.innerWidth * 2 - 1;
    const cy = -((rect.top + rect.height / 2) / window.innerHeight * 2 - 1);

    camera.updateMatrixWorld();
    ndcScratch.set(cx, cy, 0.5).unproject(camera);
    ndcScratch.sub(camera.position).normalize();
    const targetZ = glass.mesh.position.z;
    const t = (targetZ - camera.position.z) / ndcScratch.z;
    worldScratch.copy(camera.position).addScaledVector(ndcScratch, t);

    glass.mesh.position.x = worldScratch.x;
    glass.mesh.position.y = worldScratch.y;

    // 2) Scale the slab so the projected width/height matches the DOM rect.
    //    Visible-world dimensions at distance |z|, FOV.
    const distFromCam = Math.abs(camera.position.z - targetZ);
    const viewHeight = 2 * Math.tan((camera.fov * Math.PI / 360)) * distFromCam;
    const viewWidth = viewHeight * camera.aspect;
    const worldW = (rect.width / window.innerWidth) * viewWidth;
    const worldH = (rect.height / window.innerHeight) * viewHeight;

    // Glass geometry is built at 1.85 × 2.55; scale to fit. We deliberately
    // overshoot by ~6% so the refraction halo extends slightly past the DOM
    // edge — looks more like real glass than a clipped pane.
    const halo = 1.06;
    glass.mesh.scale.x = (worldW / 1.85) * halo;
    glass.mesh.scale.y = (worldH / 2.55) * halo;
  }

  /* ──────────────── RAF loop with render-on-demand ──────────────── */
  const clock = new Clock();
  let rafId = 0;
  let disposed = false;
  let frameCount = 0;
  const IDLE_MS = 4000;

  const tick = (): void => {
    if (disposed) return;
    rafId = requestAnimationFrame(tick);
    frameCount++;

    const now = performance.now();
    const idle = now - pointer.lastMoveAt > IDLE_MS;
    // When idle, only render every Nth frame. The LED pulses once per second,
    // so even at ~20 fps the pulse stays smooth.
    if (idle && frameCount % cfg.idleFrameSkip !== 0) return;

    const elapsed = clock.getElapsedTime();
    modelHandle?.tick(elapsed);

    if (cfg.parallax && !reducedMotion) {
      tickParallax(pointer, camera, rim.light, parallaxCfg);
    }
    alignGlass();

    if (postFX) postFX.composer.render();
    else renderer.render(scene, camera);
  };

  if (reducedMotion) {
    alignGlass();
    renderer.render(scene, camera);
  } else {
    tick();
  }

  /* ──────────────── Slice 4 control surface ──────────────── */

  function killTweens(): void {
    gsap.killTweensOf([rim.light, glass.mesh.position]);
    if (modelEmissive) {
      gsap.killTweensOf([modelEmissive, modelEmissive.emissive]);
    }
  }

  const setFocused = (active: boolean): void => {
    if (reducedMotion) return;
    // A focus change is "activity" — un-idle the renderer so the tweens are
    // visible. Setting lastMoveAt forces the renderer back to full rate.
    pointer.lastMoveAt = performance.now();

    const dur = 0.45;
    gsap.to(rim.light, {
      intensity: active ? rim.baseIntensity * 1.6 : rim.baseIntensity,
      duration: dur,
      ease: 'power3.out',
      overwrite: 'auto',
    });
    gsap.to(glass.mesh.position, {
      z: active ? glassFocusedZ : glassBaseZ,
      duration: dur,
      ease: 'power3.out',
      overwrite: 'auto',
    });
    if (modelEmissive) {
      gsap.to(modelEmissive, {
        emissiveIntensity: active ? emissiveBaseIntensity * 2.2 : emissiveBaseIntensity,
        duration: dur,
        ease: 'power3.out',
        overwrite: 'auto',
      });
    }
  };

  const flashError = (): void => {
    if (reducedMotion || !modelEmissive) return;
    pointer.lastMoveAt = performance.now();
    const restoreColor = modelEmissive.emissive.clone();

    gsap.timeline({ overwrite: 'auto' })
      .to(modelEmissive.emissive, {
        r: 0.97, g: 0.20, b: 0.29,
        duration: 0.18,
        ease: 'power3.out',
      })
      .to(modelEmissive, {
        emissiveIntensity: emissiveBaseIntensity * 3.0,
        duration: 0.18,
        ease: 'power3.out',
      }, '<')
      .to({}, { duration: 0.20 })
      .to(modelEmissive.emissive, {
        r: restoreColor.r,
        g: restoreColor.g,
        b: restoreColor.b,
        duration: 0.5,
        ease: 'power2.inOut',
      })
      .to(modelEmissive, {
        emissiveIntensity: emissiveBaseIntensity,
        duration: 0.5,
        ease: 'power2.inOut',
      }, '<');
  };

  return {
    tier,
    dispose(): void {
      disposed = true;
      cancelAnimationFrame(rafId);
      killTweens();
      pointerWatcher?.dispose();
      resizeWatcher.dispose();
      composerResizeRO.disconnect();
      postFX?.dispose();
      glass.dispose();
      modelHandle?.dispose();
      scene.environment = null;
      envTexture.dispose();
      renderer.dispose();
    },
    resize(): void {
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h, false);
      postFX?.resize(w, h, renderer.getPixelRatio());
    },
    setFocused,
    flashError,
  };
}
