import {
  Vector2,
  type Scene,
  type PerspectiveCamera,
  type WebGLRenderer,
} from 'three';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';

/**
 * Post-processing composer for the EVON login scene.
 *
 * Slice 5 — bloom on emissive elements (ring/LED) + final tone-map/sRGB pass.
 * Uses Three's built-in EffectComposer rather than the `postprocessing` npm
 * package — we don't get merged-pass optimization but we save ~120KB of
 * dependency weight, which on a login page is a clear win.
 *
 * If you later need merged passes (e.g. you're stacking 4+ effects and the
 * separate fullscreen draws show up in the perf profile), the `postprocessing`
 * package is the upgrade path — its EffectPass collapses multiple effects into
 * a single shader.
 */

export interface PostFXHandle {
  composer: EffectComposer;
  bloom: UnrealBloomPass;
  resize(width: number, height: number, pixelRatio: number): void;
  dispose(): void;
}

export interface PostFXOptions {
  bloomStrength: number;
  bloomRadius?: number;
  bloomThreshold?: number;
}

export function createPostFX(
  scene: Scene,
  camera: PerspectiveCamera,
  renderer: WebGLRenderer,
  opts: PostFXOptions,
): PostFXHandle {
  const size = new Vector2();
  renderer.getSize(size);

  const composer = new EffectComposer(renderer);
  composer.setPixelRatio(renderer.getPixelRatio());
  composer.setSize(size.x, size.y);

  composer.addPass(new RenderPass(scene, camera));

  const bloom = new UnrealBloomPass(
    new Vector2(size.x, size.y),
    opts.bloomStrength,
    opts.bloomRadius ?? 0.6,
    opts.bloomThreshold ?? 0.78,
  );
  composer.addPass(bloom);

  // OutputPass handles tone mapping + sRGB conversion at the end of the chain.
  // Required when using EffectComposer because the intermediate render targets
  // are linear; without this the final image is gamma-incorrect.
  composer.addPass(new OutputPass());

  return {
    composer,
    bloom,
    resize(width: number, height: number, pixelRatio: number): void {
      composer.setPixelRatio(pixelRatio);
      composer.setSize(width, height);
      bloom.resolution.set(width, height);
    },
    dispose(): void {
      composer.dispose();
    },
  };
}
