import {
  MeshPhysicalMaterial,
  MeshStandardMaterial,
} from 'three';

/**
 * PBR material factory for the EVON charging-station fallback geometry.
 *
 * Each factory returns a fresh instance so callers can mutate without
 * side-effects. The materials are tuned to read well under:
 *   - scene.environment = PMREM(RoomEnvironment)
 *   - ACES filmic tone mapping, exposure ≈ 1.0
 *   - Key directional (warm-ish white @ 0.8) + fill directional (cool @ 0.2)
 *
 * Slice 2 — replaces the prior MeshLambertMaterial palette with physically
 * based equivalents. Geometry positions in Models.ts are unchanged.
 */

/** Dark slate metal — used for the base platform. Matte-ish, lightly lacquered. */
export function basePlatformMaterial(): MeshPhysicalMaterial {
  return new MeshPhysicalMaterial({
    color: 0x2d3748,
    metalness: 0.9,
    roughness: 0.4,
    clearcoat: 0.35,
    clearcoatRoughness: 0.4,
    envMapIntensity: 1.0,
  });
}

/** EVON brand green — clear-coated lacquered column. */
export function brandColumnMaterial(): MeshPhysicalMaterial {
  return new MeshPhysicalMaterial({
    color: 0x10b981,
    metalness: 0.0,
    roughness: 0.35,
    clearcoat: 1.0,
    clearcoatRoughness: 0.05,
    envMapIntensity: 1.1,
  });
}

/** Near-black painted metal — charging head body. */
export function headMaterial(): MeshPhysicalMaterial {
  return new MeshPhysicalMaterial({
    color: 0x1f2937,
    metalness: 0.92,
    roughness: 0.18,
    clearcoat: 1.0,
    clearcoatRoughness: 0.08,
    envMapIntensity: 1.2,
  });
}

/** Matte rubber — cable. Very rough, no metal, no clearcoat. */
export function cableMaterial(): MeshPhysicalMaterial {
  return new MeshPhysicalMaterial({
    color: 0x2a323c,
    metalness: 0.0,
    roughness: 0.92,
    clearcoat: 0.0,
    envMapIntensity: 0.6,
  });
}

/** Glossy red — connector tip. Slight metal, mid roughness. */
export function connectorMaterial(): MeshPhysicalMaterial {
  return new MeshPhysicalMaterial({
    color: 0xef4444,
    metalness: 0.5,
    roughness: 0.22,
    clearcoat: 0.6,
    clearcoatRoughness: 0.1,
    envMapIntensity: 1.0,
  });
}

/**
 * Emissive LED — visually self-lit, picks up faint IBL on its rim.
 * Returned as MeshStandardMaterial because emissive support is built-in;
 * MeshPhysical would add cost we don't need on a 0.05-radius sphere.
 */
export function ledMaterial(initialHex = 0x22c55e): MeshStandardMaterial {
  return new MeshStandardMaterial({
    color: initialHex,
    emissive: initialHex,
    emissiveIntensity: 1.8,
    metalness: 0.0,
    roughness: 0.4,
  });
}

/** Translucent floating particle — soft alpha, picks up subtle env tint. */
export function particleMaterial(): MeshStandardMaterial {
  return new MeshStandardMaterial({
    color: 0x60a5fa,
    emissive: 0x60a5fa,
    emissiveIntensity: 0.6,
    transparent: true,
    opacity: 0.6,
    metalness: 0.0,
    roughness: 0.5,
  });
}
