import {
  Scene,
  PerspectiveCamera,
  WebGLRenderer,
  PCFSoftShadowMap,
  ACESFilmicToneMapping,
  SRGBColorSpace,
} from 'three';

/**
 * Scene primitives — pure construction, no side effects on document.
 *
 * Matches the visual settings of the original inline scene in login.blade.php
 * (Slice 1 = no visual change).
 */

export function createRenderer(
  canvas: HTMLCanvasElement,
  pixelRatioCap: number = 2,
): WebGLRenderer {
  const renderer = new WebGLRenderer({
    canvas,
    alpha: true,
    antialias: true,
    powerPreference: 'high-performance',
  });
  renderer.setSize(canvas.clientWidth, canvas.clientHeight);
  renderer.setClearColor(0x000000, 0);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, pixelRatioCap));

  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = PCFSoftShadowMap;
  renderer.outputColorSpace = SRGBColorSpace;
  renderer.toneMapping = ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1;

  return renderer;
}

export function createScene(): Scene {
  return new Scene();
}

export function createCamera(canvas: HTMLCanvasElement): PerspectiveCamera {
  // Slice 3: canvas is now full-bleed (the form sits over it instead of beside it).
  // FOV narrowed from 75 → 38 for a cinematic crop; camera pulled back slightly
  // and angled so the pillar reads on the left half of frame.
  const camera = new PerspectiveCamera(
    38,
    canvas.clientWidth / canvas.clientHeight,
    0.1,
    100,
  );
  camera.position.set(0, 1.6, 5.5);
  camera.lookAt(0.2, 1.1, 0);
  return camera;
}
