import {
  Scene,
  DirectionalLight,
  SpotLight,
  Object3D,
  WebGLRenderer,
  PMREMGenerator,
  Texture,
} from 'three';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';

/**
 * Lighting setup for the EVON login scene.
 *
 * Slice 2 — IBL added via RoomEnvironment (procedural studio). The previous
 * AmbientLight was removed because IBL fills that role with much richer per-
 * direction information. The key/fill directional lights remain to give the
 * scene directional shadow and silhouette definition.
 *
 * Slice 4+ will add a cursor-tracked rim spotlight and reposition lights for
 * the redesigned composition.
 */

/**
 * Adds key + fill directional lights to the scene.
 *
 * Same positions and (near-)same intensities as the original inline scene;
 * the only adjustment is dropping the fill from 0.3 → 0.2 because IBL now
 * provides the ambient base that the fill used to compensate for.
 */
export function setupLights(scene: Scene, shadowMapSize: number = 2048): void {
  const key = new DirectionalLight(0xffffff, 0.8);
  key.position.set(10, 10, 5);
  key.castShadow = true;
  key.shadow.mapSize.width = shadowMapSize;
  key.shadow.mapSize.height = shadowMapSize;
  key.shadow.camera.near = 0.5;
  key.shadow.camera.far = 50;
  scene.add(key);

  const fill = new DirectionalLight(0xffffff, 0.2);
  fill.position.set(-10, 5, -5);
  scene.add(fill);
}

/**
 * Rim spotlight handle — exposed so the parallax driver can sweep its position
 * with the cursor, and the focus/error timelines can tween its intensity.
 */
export interface RimLight {
  light: SpotLight;
  target: Object3D;
  /** Base position before parallax offsets are applied. */
  basePosition: { x: number; y: number; z: number };
  /** Base intensity before focus/error tweens are applied. */
  baseIntensity: number;
}

/**
 * Adds an EVON-green rim spotlight that sits behind the pillar, defining its
 * silhouette. The light is positioned for the Slice 3 composition (pillar at
 * world x = -0.8) and is sweep-target for the parallax driver in Slice 4.
 */
export function setupRimLight(scene: Scene): RimLight {
  const baseIntensity = 14;
  const light = new SpotLight(0x10E0A0, baseIntensity, 14, Math.PI * 0.18, 0.55, 1.0);
  light.position.set(-0.8, 3.2, -3.4);
  light.castShadow = false; // intentional — only key directional casts shadows

  const target = new Object3D();
  target.position.set(-0.8, 1.8, 0); // aims at the pillar's top third
  scene.add(light, target);
  light.target = target;

  return {
    light,
    target,
    basePosition: { x: -0.8, y: 3.2, z: -3.4 },
    baseIntensity,
  };
}

/**
 * Generates a PMREM-prefiltered environment map from a procedural RoomEnvironment
 * and assigns it to scene.environment so all PBR materials pick up IBL.
 *
 * Returns the generated Texture so the caller can dispose it on scene tear-down.
 * The PMREMGenerator and the source RoomEnvironment are disposed immediately
 * after the texture is built — they're not needed at runtime.
 */
export function setupEnvironment(scene: Scene, renderer: WebGLRenderer): Texture {
  const pmrem = new PMREMGenerator(renderer);
  pmrem.compileEquirectangularShader();

  const roomEnv = new RoomEnvironment();
  const target = pmrem.fromScene(roomEnv, 0.04);

  scene.environment = target.texture;
  // scene.background stays null — the canvas remains transparent so the page
  // gradient behind it continues to show through.

  pmrem.dispose();
  // RoomEnvironment is a regular Scene full of meshes; dispose its geometry
  // and material so the GC can reclaim them.
  roomEnv.traverse((obj) => {
    const maybeMesh = obj as { geometry?: { dispose(): void }; material?: { dispose(): void } | { dispose(): void }[] };
    maybeMesh.geometry?.dispose();
    if (Array.isArray(maybeMesh.material)) {
      for (const m of maybeMesh.material) m.dispose();
    } else {
      maybeMesh.material?.dispose();
    }
  });

  return target.texture;
}
